/* Ephemeral tutorial state only. Real popup clocks pause via home-progress.js. */
(() => {
  'use strict';
  const L=LearningCore,E=Engine,symbols=['🍎','🍋','🍇'],fruit=['사과','레몬','포도'];
  const dialog=document.createElement('dialog');dialog.id='popup-picture-practice';dialog.setAttribute('aria-labelledby','popup-practice-title');document.body.appendChild(dialog);
  let game='baseball',step=0,guess='',comparison=null,solved=false,message='',memory=null,hint=false;
  const lessons=()=>game==='baseball'?L.baseballLessons:L.memoryLessons,name=()=>game==='baseball'?'숫자야구':'기억의 짝';
  const digits=value=>`<div class="practice-digits" style="grid-template-columns:repeat(${value.length},minmax(0,1fr))">${[...value].map((n,i)=>`<span><small>${i+1}번째</small><b>${n}</b></span>`).join('')}</div>`;
  function reset(){guess=lessons()[step].guess||'';comparison=null;solved=false;message='';hint=false;memory=game==='memory'?{deck:lessons()[step].deck.slice(),open:[],matched:[],errors:0}:null;render();}
  function baseballView(){const p=lessons()[step];return `<p>연습에서는 정답을 공개해 두 줄을 비교해요. 본게임은 정답을 숨기고 S·B 개수만 알려줍니다.</p><h4>연습 정답 · ${p.secret.length}자리 (첫 자리 0도 가능)</h4>${digits(p.secret)}${p.guess?`<h4>비교할 입력</h4>${digits(guess)}<button type="button" class="primary" data-popup-check>그림으로 S·B 확인</button>`:`<form data-popup-baseball-form><label for="practice-baseball-input">0~9 중 서로 다른 숫자 ${p.secret.length}자리</label><input id="practice-baseball-input" name="guess" inputmode="numeric" maxlength="${p.secret.length}" autocomplete="off" value="${guess}" placeholder="${p.secret}"><button type="submit" class="primary">S·B 확인</button></form><p>몇 번이든 다시 입력해도 괜찮아요. 위 정답과 비교해보세요.</p>`}${comparison?`<div class="practice-code-results">${L.codeComparison(p.secret,guess).map(c=>`<div class="clue-${c.kind}"><b>${c.digit}</b><span>${c.kind==='exact'?`↓ ${c.index+1}번째 자리 · S`:c.kind==='misplaced'?`↔ 정답 ${c.target+1}번째 자리 · B`:'× 포함되지 않음'}</span></div>`).join('')}</div><p class="practice-score-total">${comparison.strikes}S ${comparison.balls}B${comparison.strikes+comparison.balls===0?' · 아웃':''}</p>`:''}`;}
  function memoryView(){return `<p>카드를 두 장씩 뒤집어 같은 과일을 찾아보세요. 서로 다르면 충분히 본 뒤 직접 닫아요.</p><p class="practice-note">연습은 ${memory.deck.length/2}쌍 · 시간·오답·점수 제한 없음<br>본게임은 16장 8쌍 · 120초이며 다른 두 카드는 1.2초 후 닫힙니다.</p><div class="practice-memory-board" style="grid-template-columns:repeat(${memory.deck.length<=4?2:3},minmax(0,1fr))" role="group" aria-label="시간제한 없는 연습 카드">${memory.deck.map((n,i)=>{const open=memory.open.includes(i),matched=memory.matched.includes(i),shown=open||matched||hint;return `<button type="button" class="tile ${shown?'open':''} ${matched?'matched':''}" data-popup-memory="${i}" aria-label="연습 ${i+1}번 ${shown?fruit[n]:'카드 뒤집기'}${matched?' · 찾은 짝':''}" ${matched||open||memory.open.length===2?'disabled':''}><small>${i+1}번</small><span>${shown?symbols[n]:'?'}</span><small>${matched?'찾은 짝':open?'뒤집은 카드':hint?'그림 힌트':'눌러보기'}</small></button>`;}).join('')}</div><p class="practice-score-total">찾은 짝 ${memory.matched.length/2}/${memory.deck.length/2}</p>${memory.open.length===2?'<button type="button" class="primary" data-popup-memory-close>다른 두 카드 확인했어요 · 다시 닫기</button>':''}<button type="button" data-popup-memory-hint>${hint?'전체 그림 힌트 숨기기':'전체 그림 힌트 보기'}</button>`;}
  function render(){dialog.innerHTML=`<div class="dialog-head"><span>그림으로 배우기 · ${step+1}/${lessons().length}</span><button type="button" data-popup-practice-close aria-label="${name()} 연습 닫기">닫기</button></div><h2 id="popup-practice-title" tabindex="-1">${name()} · 그림 연습</h2><p class="practice-note">실제 게임의 진행과 완료 기록은 바뀌지 않아요. 연습창이 열려 있는 동안 진행 중인 실제 게임의 제한시간도 멈춥니다.</p><h3>${lessons()[step].title}</h3>${game==='baseball'?baseballView():memoryView()}<p class="light-practice-status" role="status" aria-live="polite">${message||'그림을 보며 천천히 눌러보세요. 시간·횟수 제한은 없어요.'}</p><div class="actions practice-actions"><button type="button" data-popup-practice-reset>이 연습 다시 하기</button>${solved&&step<lessons().length-1?'<button type="button" class="primary" data-popup-practice-next>다음 연습 →</button>':''}</div><button type="button" class="practice-entry light-return" data-popup-practice-close>${solved&&step===lessons().length-1?'연습 완료 · 게임 화면으로 돌아가기':'게임 화면으로 돌아가기'}</button>`;}
  function check(value){const p=lessons()[step];if(!/^\d+$/.test(value)||value.length!==p.secret.length||new Set(value).size!==p.secret.length){message=`0~9 중 서로 다른 숫자 ${p.secret.length}자리를 입력해주세요. 횟수는 줄지 않아요.`;render();return;}guess=value;comparison=E.baseballScore(p.secret,guess);solved=step<3||comparison.strikes===p.secret.length;message=solved?'잘했어요! 그림으로 단서를 확인했어요. 실제 기록에는 포함되지 않아요.':'S는 같은 자리, B는 다른 자리예요. 화살표를 보고 다시 입력해보세요.';render();if(step>=3&&!solved)dialog.querySelector('input').focus();}
  dialog.addEventListener('submit',e=>{e.preventDefault();check(new FormData(e.target).get('guess').trim());});
  dialog.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.hasAttribute('data-popup-practice-close'))dialog.close();else if(b.hasAttribute('data-popup-practice-reset')){reset();dialog.querySelector('h2').focus();}else if(b.hasAttribute('data-popup-practice-next')){step++;reset();dialog.querySelector('h2').focus();}else if(b.hasAttribute('data-popup-check'))check(guess);else if(b.hasAttribute('data-popup-memory-hint')){hint=!hint;render();}else if(b.hasAttribute('data-popup-memory-close')){memory={...memory,open:[]};message='다른 두 장을 닫았어요. 위치를 기억하고 다른 카드와 짝을 맞춰보세요.';render();}else if(b.hasAttribute('data-popup-memory')){const before=memory;memory=L.memoryFlip(memory,+b.dataset.popupMemory);solved=memory.matched.length===memory.deck.length;message=solved?'모든 짝을 찾았어요! 연습 결과는 실제 기록에 포함되지 않아요.':memory.open.length===2?'서로 다른 그림이에요. 천천히 위치를 기억한 뒤 다시 닫기를 눌러주세요.':memory.matched.length>before.matched.length?'같은 그림이에요! 찾은 짝은 열린 채로 남아요.':'한 장을 뒤집었어요. 다른 한 장을 골라보세요.';render();}});
  function open(id){if(!['baseball','memory'].includes(id))return;game=id;step=0;reset();dialog.showModal();dialog.querySelector('h2').focus();}
  const originalRules=showGameRules;showGameRules=function(id){const result=originalRules(id);if(['baseball','memory'].includes(id)){const b=document.createElement('button');b.type='button';b.className='practice-entry';b.textContent='시간제한 없는 그림 연습';b.addEventListener('click',()=>{open(id);document.querySelector('#game-rules').close();});document.querySelector('#game-rules-content').appendChild(b);}return result;};
  window.PopupPractice={open};
})();
